 56→  function element(tag, className, text) {
 57→    var node = document.createElement(tag);
 58→    if (className) {
 59→      node.className = className;
 60→    }
 61→    if (text !== undefined && text !== null) {
 62→      node.textContent = String(text);
 63→    }
 64→    return node;
 65→  }
 66→
 67→  function showError(id, message) {
 68→    var node = document.getElementById(id);
 69→    node.textContent = message;
 70→    node.hidden = false;
 71→  }
 72→
 73→  function clearError(id) {
 74→    var node = document.getElementById(id);
 75→    node.textContent = "";
 76→    node.hidden = true;
 77→  }
 78→
 79→  function show(node) {
 80→    node.hidden = false;
 81→  }
 82→
 83→  function hide(node) {
 84→    node.hidden = true;
 85→  }
 86→
 87→  function request(method, path, body) {
 88→    var options = { method: method };
 89→    if (body !== undefined) {
 90→      options.headers = { "Content-Type": "application/json" };
 91→      options.body = JSON.stringify(body);
 92→    }
 93→    return fetch(path, options).then(function (response) {
 94→      return response.json().then(function (payload) {
 95→        if (!response.ok) {
 96→          var reason = payload && payload.error ? payload.error : "Something went wrong. Please try again.";
 97→          throw new Error(reason);
 98→        }
 99→        return payload;
100→      });
101→    });
102→  }
