104→  // ------------------------------------------------------------- step one
105→
106→  CATEGORIES.forEach(function (category) {
107→    var card = element("button", "option-card", category.label);
108→    card.type = "button";
109→    card.addEventListener("click", function () {
110→      state.category = category.id;
111→      Array.prototype.forEach.call(categoryOptions.children, function (child) {
112→        child.classList.remove("selected");
113→      });
114→      card.classList.add("selected");
115→      document.getElementById("category-next").disabled = false;
116→      // Changing the category resets everything downstream (R3 page side): the trip
117→      // list belongs to the category, so a trip picked for one category must never
118→      // survive a switch to another.
119→      state.tripId = null;
120→      while (tripOptions.firstChild) {
121→        tripOptions.removeChild(tripOptions.firstChild);
122→      }
123→      document.getElementById("trip-next").disabled = true;
124→      clearError("trip-error");
125→      clearError("details-error");
126→      hide(stepTrip);
127→      hide(stepDetails);
