132→  document.getElementById("category-next").addEventListener("click", function () {
133→    clearError("category-error");
134→    hide(stepCategory);
135→    show(stepTrip);
136→    hide(stepDetails);
137→    loadTrips();
138→    window.scrollTo(0, 0);
