141→  // ------------------------------------------------------------- step two
142→
143→  function loadTrips() {
144→    var boxes = tripOptions;
145→    while (boxes.firstChild) {
146→      boxes.removeChild(boxes.firstChild);
147→    }
148→    state.tripId = null;
149→    document.getElementById("trip-next").disabled = true;
150→    boxes.appendChild(element("p", "loading", "Loading trips…"));
151→    request("GET", "/api/trips?category=" + encodeURIComponent(state.category))
152→      .then(function (payload) {
153→        while (boxes.firstChild) {
154→          boxes.removeChild(boxes.firstChild);
155→        }
156→        state.trips = Array.isArray(payload.trips) ? payload.trips : [];
157→        if (state.trips.length === 0) {
158→          boxes.appendChild(element("p", "hint", "No trips are available in the sample dataset."));
159→          return;
160→        }
161→        state.trips.forEach(function (trip) {
162→          var meta = [trip.date, trip.kind_label].filter(Boolean).join(" · ");
163→          var lines = [
164→            element("strong", null, trip.label),
165→            element("span", "trip-meta", meta)
166→          ];
167→          var charge = "";
168→          if (trip.fare_sgd !== null && trip.fare_sgd !== undefined) {
169→            charge = " · SGD " + Number(trip.fare_sgd).toFixed(2)
170→              + (trip.charge_label ? " " + trip.charge_label : "");
171→          }
172→          var detail = element("span", "trip-meta", "");
173→          detail.textContent = "Trip " + trip.trip_id + charge;
174→          var card = element("button", "option-card trip-card");
175→          card.type = "button";
176→          lines.forEach(function (line) { card.appendChild(line); });
177→          card.appendChild(detail);
178→          card.addEventListener("click", function () {
179→            state.tripId = trip.trip_id;
180→            Array.prototype.forEach.call(boxes.children, function (child) {
181→              child.classList.remove("selected");
182→            });
183→            card.classList.add("selected");
184→            document.getElementById("trip-next").disabled = false;
185→          });
186→          boxes.appendChild(card);
187→        });
188→      })
189→      .catch(function (error) {
190→        while (boxes.firstChild) {
191→          boxes.removeChild(boxes.firstChild);
192→        }
193→        showError("trip-error", error.message);
194→      });
195→  }
196→
197→  document.getElementById("trip-back").addEventListener("click", function () {
198→    show(stepCategory);
199→    hide(stepTrip);
200→  });
201→
202→  document.getElementById("trip-next").addEventListener("click", function () {
203→    clearError("trip-error");
204→    hide(stepTrip);
205→    buildQuestions();
206→    show(stepDetails);
207→    window.scrollTo(0, 0);
