210→  // --------------------------------------------------------- step three
211→
212→  function buildChoiceQuestion(question) {
213→    var field = element("div", "field");
214→    var label = element("label", null, question.label);
215→    // The choices container is a div, so a <label for> cannot point at it. The
216→    // question text reaches assistive tech via role="group" + aria-labelledby.
217→    label.id = "label-" + question.key;
218→    var choices = element("div", "choice-options");
219→    choices.id = "answer-" + question.key;
220→    choices.role = "group";
221→    choices.setAttribute("aria-labelledby", "label-" + question.key);
222→    var elaborate = element("textarea", "answer-input elaborate");
223→    elaborate.rows = 2;
224→    elaborate.setAttribute("data-elaborate-for", question.key);
225→    elaborate.placeholder = "Tell us more (optional)";
226→    elaborate.hidden = true;
227→
228→    ["Yes", "No"].forEach(function (choice) {
229→      var button = element("button", "choice-button", choice);
230→      button.type = "button";
231→      button.setAttribute("data-choice", choice);
232→      button.setAttribute("aria-pressed", "false");
233→      button.dataset.questionKey = question.key;
234→      button.addEventListener("click", function () {
235→        Array.prototype.forEach.call(choices.children, function (sibling) {
236→          sibling.classList.remove("selected");
237→          sibling.setAttribute("aria-pressed", "false");
238→        });
239→        button.classList.add("selected");
240→        button.setAttribute("aria-pressed", "true");
241→        show(elaborate);
242→      });
243→      choices.appendChild(button);
244→    });
245→
246→    field.appendChild(label);
247→    field.appendChild(choices);
248→    field.appendChild(elaborate);
249→    return field;
250→  }
251→
252→  function buildQuestions() {
253→    while (questionList.firstChild) {
254→      questionList.removeChild(questionList.firstChild);
255→    }
256→    var questions = QUESTIONNAIRES[state.category] || [];
257→    questions.forEach(function (question) {
258→      if (question.kind === "yes_no") {
259→        questionList.appendChild(buildChoiceQuestion(question));
260→      } else if (question.kind === "open") {
261→        var field = element("div", "field");
262→        var label = element("label", null, question.label);
263→        label.htmlFor = "answer-" + question.key;
264→        var input = element("textarea", "answer-input");
265→        input.id = "answer-" + question.key;
266→        input.rows = 2;
267→        input.dataset.questionKey = question.key;
268→        field.appendChild(label);
269→        field.appendChild(input);
270→        questionList.appendChild(field);
271→      }
272→    });
273→  }
274→
275→  document.getElementById("details-back").addEventListener("click", function () {
276→    hide(stepDetails);
277→    show(stepTrip);
278→    loadTrips();
279→  });
280→
281→  document.getElementById("details-form").addEventListener("submit", function (event) {
282→    event.preventDefault();
283→    clearError("details-error");
284→    var description = document.getElementById("description").value;
285→    if (!description.trim()) {
286→      showError("details-error", "Please tell us what happened before sending.");
287→      return;
288→    }
289→    var amountText = document.getElementById("claim-amount").value.trim();
290→    var amount = null;
291→    if (amountText !== "") {
292→      amount = Number(amountText);
293→      if (!isFinite(amount) || amount < 0 || amount > 500) {
294→        showError("details-error", "The amount must be between 0 and 500 SGD.");
295→        return;
296→      }
297→    }
298→    var answers = {};
299→    (QUESTIONNAIRES[state.category] || []).forEach(function (question) {
300→      if (question.kind === "yes_no") {
301→        var selected = questionList.querySelector(
302→          '.choice-button.selected[data-question-key="' + question.key + '"]'
303→        );
304→        var elaborate = questionList.querySelector(
305→          'textarea[data-elaborate-for="' + question.key + '"]'
306→        );
307→        var choice = selected ? selected.dataset.choice : "";
308→        var elaboration = elaborate ? elaborate.value.trim() : "";
309→        answers[question.key] = choice
310→          ? (elaboration ? choice + " - " + elaboration : choice)
311→          : "";
312→      } else if (question.kind === "open") {
313→        var input = questionList.querySelector(
314→          'textarea[data-question-key="' + question.key + '"]'
315→        );
316→        answers[question.key] = input ? input.value : "";
317→      }
318→    });
319→
320→    var submit = document.getElementById("details-submit");
321→    submit.disabled = true;
322→    request("POST", "/api/disputes", {
323→      category: state.category,
324→      filed_by: "rider",
325→      trip_id: state.tripId,
326→      description: description,
327→      claim_amount_sgd: amount,
328→      answers: answers
329→    })
330→      .then(function (view) {
331→        renderOutcome(view);
332→      })
333→      .catch(function (error) {
334→        submit.disabled = false;
335→        showError("details-error", error.message);
336→      });
337→  });
338→
339→  // ------------------------------------------------------------- outcome
340→
341→  function renderOutcome(view) {
342→    hide(document.getElementById("form-steps"));
343→    show(outcomePanel);
344→    state.runId = view.run_id;
345→    outcomeTitle.textContent = STATUS_HEADINGS[view.status] || "Your dispute has been received";
346→    outcomeReference.textContent = view.dispute_id;
347→    outcomeMessage.textContent = view.message;
348→    hide(outcomeStatus);
349→    buildAnswerBoxes(view);
350→    window.scrollTo(0, 0);
351→  }
352→
353→  function buildAnswerBoxes(view) {
354→    while (questionBoxes.firstChild) {
355→      questionBoxes.removeChild(questionBoxes.firstChild);
356→    }
357→    var questions = Array.isArray(view.questions) ? view.questions : [];
358→    if (view.status !== "needs_info" || questions.length === 0) {
359→      hide(outcomeQuestions);
360→      return;
361→    }
362→    show(outcomeQuestions);
363→    questions.forEach(function (question, index) {
364→      var field = element("div", "field");
365→      var label = element("label", null, question);
366→      label.htmlFor = "reply-" + index;
367→      var input = element("textarea", "answer-input");
368→      input.id = "reply-" + index;
369→      input.rows = 2;
370→      field.appendChild(label);
371→      field.appendChild(input);
372→      questionBoxes.appendChild(field);
373→    });
374→  }
375→
376→  document.getElementById("answers-submit").addEventListener("click", function () {
377→    clearError("answers-error");
378→    var replies = [];
379→    var complete = true;
380→    Array.prototype.forEach.call(questionBoxes.querySelectorAll("textarea"), function (input) {
381→      var label = questionBoxes.querySelector('label[for="' + input.id + '"]');
382→      replies.push({ question: label ? label.textContent : "", answer: input.value });
383→      if (!input.value.trim()) {
384→        complete = false;
385→      }
386→    });
387→    if (!complete) {
388→      showError("answers-error", "Please answer each question before sending.");
389→      return;
390→    }
391→    var submit = document.getElementById("answers-submit");
392→    submit.disabled = true;
393→    outcomeStatus.textContent = "Sending your answers…";
394→    show(outcomeStatus);
395→    request("POST", "/api/disputes/" + encodeURIComponent(state.runId) + "/answers", {
396→      answers: replies
397→    })
398→      .then(function (view) {
399→        renderOutcome(view);
400→      })
401→      .catch(function (error) {
402→        submit.disabled = false;
403→        hide(outcomeStatus);
404→        showError("answers-error", error.message);
405→      });
406→  });
407→}());
